// ── State ────────────────────────────────────────────────────
const STATE = {
  year: parseInt(localStorage.getItem('mdrs_year') || '1'),
  progress: JSON.parse(localStorage.getItem('mdrs_progress') || '{}'),
  scores: JSON.parse(localStorage.getItem('mdrs_scores') || '{}'),
};

// ── Save state to localStorage ───────────────────────────────
function saveState() {
  localStorage.setItem('mdrs_year', STATE.year);
  localStorage.setItem('mdrs_progress', JSON.stringify(STATE.progress));
  localStorage.setItem('mdrs_scores', JSON.stringify(STATE.scores));
}

// ── Year Selector (buttons and/or dropdown) ──────────────────
function initYearSelector() {
  const btns = document.querySelectorAll('.year-btn');
  const sel = document.querySelector('.year-select');
  if (!btns.length && !sel) return;
  function setYear(yr) {
    STATE.year = yr;
    saveState();
    btns.forEach(b => b.classList.toggle('active', parseInt(b.dataset.year) === yr));
    if (sel) sel.value = String(yr);
    applyYearFilter();
  }
  btns.forEach(btn => btn.addEventListener('click', () => setYear(parseInt(btn.dataset.year))));
  if (sel) sel.addEventListener('change', () => setYear(parseInt(sel.value)));
  setYear(STATE.year);
}

function applyYearFilter() {
  // "Badge only, never hide": light up the badge for the student's current year
  // so the toggle gives feedback, but nothing on the page is ever hidden.
  document.querySelectorAll('.year-badge[data-year]').forEach(el => {
    el.classList.toggle('year-match', parseInt(el.dataset.year) === STATE.year);
  });
  // Legacy per-block reveal (a handful of index/lesson pages still use it)
  document.querySelectorAll('[data-min-year]').forEach(el => {
    const min = parseInt(el.dataset.minYear || '1');
    const max = parseInt(el.dataset.maxYear || '5');
    el.style.display = (STATE.year >= min && STATE.year <= max) ? '' : 'none';
  });
}

// ── Nav active state ─────────────────────────────────────────
function initNav() {
  const path = window.location.pathname;
  document.querySelectorAll('.nav-item a').forEach(a => {
    if (path.includes(a.getAttribute('href').replace('../', ''))) {
      a.closest('.nav-item')?.classList.add('active');
    }
  });
}

// ── Nav dropdown (tap-to-toggle for touch; CSS handles hover) ──
function initNavDropdown() {
  document.querySelectorAll('.nav-item.has-dropdown > a').forEach(link => {
    link.addEventListener('click', (e) => {
      const item = link.closest('.nav-item.has-dropdown');
      if (!item) return;
      if (window.matchMedia('(hover: none)').matches) {
        e.preventDefault();
        const wasOpen = item.classList.contains('open');
        document.querySelectorAll('.nav-item.has-dropdown.open').forEach(o => o.classList.remove('open'));
        if (!wasOpen) item.classList.add('open');
      }
    });
  });
  document.addEventListener('click', (e) => {
    document.querySelectorAll('.nav-item.has-dropdown.open').forEach(item => {
      if (!item.contains(e.target)) item.classList.remove('open');
    });
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      document.querySelectorAll('.nav-item.has-dropdown.open').forEach(o => o.classList.remove('open'));
    }
  });
}

// ── True / False Quiz ────────────────────────────────────────
function initTrueFalse() {
  document.querySelectorAll('[data-quiz="tf"]').forEach(container => {
    const id = container.dataset.quizId;
    let score = 0, answered = 0;
    const questions = container.querySelectorAll('.tf-question');
    const total = questions.length;

    questions.forEach((q, i) => {
      const correct = q.dataset.answer === 'true';
      const trueBtn = q.querySelector('.tf-btn[data-val="true"]');
      const falseBtn = q.querySelector('.tf-btn[data-val="false"]');

      [trueBtn, falseBtn].forEach(btn => {
        if (!btn) return;
        btn.addEventListener('click', () => {
          if (q.dataset.answered) return;
          q.dataset.answered = '1';
          answered++;
          const userTrue = btn.dataset.val === 'true';
          const isCorrect = userTrue === correct;
          if (isCorrect) score++;
          btn.classList.add(isCorrect ? 'correct' : 'incorrect');
          (userTrue ? falseBtn : trueBtn)?.classList.add(correct ? 'correct' : '');
          if (answered === total) showQuizScore(container, score, total, id);
        });
      });
    });
  });
}

// ── Multiple Choice Quiz ─────────────────────────────────────
function initMCQ() {
  document.querySelectorAll('[data-quiz="mcq"]').forEach(container => {
    const id = container.dataset.quizId;
    let score = 0, answered = 0;
    const questions = container.querySelectorAll('.mcq-question');
    const total = questions.length;

    questions.forEach(q => {
      const correctIdx = parseInt(q.dataset.correct);
      const options = q.querySelectorAll('.mcq-option');

      options.forEach((opt, i) => {
        opt.addEventListener('click', () => {
          if (q.dataset.answered) return;
          q.dataset.answered = '1';
          answered++;
          const isCorrect = i === correctIdx;
          if (isCorrect) score++;
          opt.classList.add(isCorrect ? 'correct' : 'wrong');
          options[correctIdx]?.classList.add('correct');
          if (answered === total) showQuizScore(container, score, total, id);
        });
      });
    });
  });
}

// ── Fill in the Blank ────────────────────────────────────────
function initFillBlank() {
  document.querySelectorAll('[data-quiz="fitb"]').forEach(container => {
    const id = container.dataset.quizId;
    const checkBtn = container.querySelector('.btn-check-fitb');
    if (!checkBtn) return;

    checkBtn.addEventListener('click', () => {
      let score = 0;
      const blanks = container.querySelectorAll('.fitb-blank');
      blanks.forEach(blank => {
        const userAnswer = blank.value.trim();
        const correct = blank.dataset.answer;
        const alts = (blank.dataset.alt || '').split('|').filter(Boolean);
        const allAccepted = [correct, ...alts].map(s => s.trim().toLowerCase());
        const isCorrect = allAccepted.includes(userAnswer.toLowerCase());
        blank.classList.toggle('correct', isCorrect);
        blank.classList.toggle('incorrect', !isCorrect);
        if (isCorrect) score++;
      });
      const total = blanks.length;
      showQuizScore(container, score, total, id);
    });
  });
}

// ── Score Display ────────────────────────────────────────────
function showQuizScore(container, score, total, id) {
  const pct = Math.round((score / total) * 100);

  // Save score
  if (id) {
    STATE.scores[id] = { score, total, pct, date: new Date().toISOString() };
    saveState();
  }

  let panel = container.querySelector('.score-panel');
  if (!panel) {
    panel = document.createElement('div');
    panel.className = 'score-panel';
    container.appendChild(panel);
  }

  const msg = pct === 100 ? 'ممتاز! أحسنت' :
              pct >= 80  ? 'جيد جداً' :
              pct >= 60  ? 'جيد، استمر' :
                           'راجع الدرس مرة أخرى';

  panel.innerHTML = `
    <div class="score-number">${score}/${total}</div>
    <div class="score-label">${pct}% correct</div>
    <div class="score-msg-ar">${msg}</div>
    <button class="btn-secondary mt-md" onclick="resetQuiz(this)">Try again — حاول مرة أخرى</button>
  `;
  panel.classList.add('visible');
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// ── Reset a quiz ─────────────────────────────────────────────
window.resetQuiz = function(btn) {
  const container = btn.closest('[data-quiz]');
  if (!container) return;

  container.querySelectorAll('[data-answered]').forEach(el => {
    delete el.dataset.answered;
  });
  container.querySelectorAll('.tf-btn').forEach(b => {
    b.classList.remove('correct', 'incorrect');
  });
  container.querySelectorAll('.mcq-option').forEach(o => {
    o.classList.remove('correct', 'wrong', 'selected');
  });
  container.querySelectorAll('.fitb-blank').forEach(b => {
    b.value = '';
    b.classList.remove('correct', 'incorrect');
  });

  const panel = container.querySelector('.score-panel');
  if (panel) panel.classList.remove('visible');
};

// ── Vocabulary Flashcards ────────────────────────────────────
// Arabic-first flashcard. Front = the vowelled Arabic only (read it first).
// Tap flips to the meaning; transliteration lives under a "peek" toggle so the
// student only glances at it if stuck — reducing the crutch (immersion rule 6).
function initFlashcards() {
  document.querySelectorAll('.vocab-card').forEach(card => {
    const ar = card.dataset.ar || card.querySelector('.vocab-ar')?.textContent || '';
    const translit = card.dataset.translit || '';
    const en = card.dataset.en || '';
    const root = card.dataset.root || '';
    const back = card.dataset.definition || '';
    const example = card.dataset.example || '';

    const frontHTML = `
      <span class="vocab-ar">${ar}</span>
      <span class="vocab-hint">اِقْرَأْ ثُمَّ اكْشِفْ · tap</span>
    `;
    const backHTML = `
      <span class="vocab-en" style="font-size:1rem;font-weight:600;color:var(--teal-deep)">${en || back}</span>
      ${back && en ? `<span class="vocab-def">${back}</span>` : ''}
      ${example ? `<span class="vocab-root" style="font-style:italic">"${example}"</span>` : ''}
      ${root ? `<span class="vocab-root">الجَذْر · ${root}</span>` : ''}
      ${translit ? `<details class="vocab-peek"><summary>النُّطْق · say it</summary><span class="vocab-transliteration">${translit}</span></details>` : ''}
    `;

    card.innerHTML = frontHTML;
    card.dataset.face = 'front';
    let flipped = false;

    card.addEventListener('click', (e) => {
      // Opening the pronunciation peek must not flip the card.
      if (e.target.closest('.vocab-peek')) return;
      flipped = !flipped;
      card.dataset.face = flipped ? 'back' : 'front';
      card.innerHTML = flipped ? backHTML : frontHTML;
    });
  });
}

// ── Progress tracking ────────────────────────────────────────
function markLessonComplete(lessonId) {
  STATE.progress[lessonId] = { done: true, date: new Date().toISOString() };
  saveState();
  updateProgressIndicators();
}

function updateProgressIndicators() {
  document.querySelectorAll('[data-lesson-id]').forEach(el => {
    const id = el.dataset.lessonId;
    const status = el.querySelector('.lesson-status');
    if (!status) return;
    if (STATE.progress[id]?.done) {
      status.classList.remove('current', 'locked');
      status.classList.add('done');
    }
  });
}

// ── Progress bar ─────────────────────────────────────────────
function updateProgressBar(lessonId, pagesRead, totalPages) {
  const bar = document.querySelector('.progress-fill');
  if (!bar) return;
  const pct = Math.round((pagesRead / totalPages) * 100);
  bar.style.width = pct + '%';
}

// ── Smooth section navigation (sidebar links) ────────────────
function initSmoothNav() {
  document.querySelectorAll('.lesson-list a[href^="#"]').forEach(a => {
    a.addEventListener('click', e => {
      e.preventDefault();
      const target = document.querySelector(a.getAttribute('href'));
      if (target) {
        const offset = 90; // account for sticky header
        const top = target.getBoundingClientRect().top + window.scrollY - offset;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    });
  });
}

// ── Observe sections for active sidebar highlight ────────────
function initScrollSpy() {
  const sections = document.querySelectorAll('[data-section]');
  const links = document.querySelectorAll('.lesson-list a[href^="#"]');
  if (!sections.length || !links.length) return;

  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const id = entry.target.dataset.section;
        links.forEach(a => {
          a.classList.toggle('active', a.getAttribute('href') === '#' + id);
        });
      }
    });
  }, { rootMargin: '-90px 0px -60% 0px' });

  sections.forEach(s => observer.observe(s));
}

// ── Grammar drill: check answers ─────────────────────────────
function initGrammarDrills() {
  document.querySelectorAll('[data-drill]').forEach(drill => {
    const checkBtn = drill.querySelector('.btn-check-drill');
    if (!checkBtn) return;

    checkBtn.addEventListener('click', () => {
      let correct = 0;
      const inputs = drill.querySelectorAll('input[data-answer]');
      inputs.forEach(inp => {
        const answer = inp.dataset.answer.trim();
        const alts = (inp.dataset.alt || '').split('|').filter(Boolean);
        const accepted = [answer, ...alts].map(s => s.trim());
        const isOk = accepted.some(a => a.toLowerCase() === inp.value.trim().toLowerCase());
        inp.classList.toggle('correct', isOk);
        inp.classList.toggle('incorrect', !isOk);
        if (isOk) correct++;
      });
      const pct = Math.round((correct / inputs.length) * 100);
      let fb = drill.querySelector('.drill-feedback');
      if (!fb) { fb = document.createElement('p'); fb.className = 'drill-feedback mt-md'; drill.appendChild(fb); }
      fb.style.color = pct >= 80 ? 'var(--year1)' : 'var(--gold-warm)';
      fb.textContent = `${correct}/${inputs.length} correct — ${pct >= 80 ? 'أحسنت!' : 'Keep practicing!'}`;
    });
  });
}

// ── AI Quiz Generator (calls Anthropic API) ──────────────────
async function generateAIQuiz(lessonContent, lessonTitle, targetEl) {
  if (!targetEl) return;
  targetEl.innerHTML = '<p style="color:var(--ink-light);text-align:center">⟳ Generating questions...</p>';

  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-sonnet-4-6',
        max_tokens: 1000,
        messages: [{
          role: 'user',
          content: `You are an Islamic studies teacher. Create 4 multiple choice questions testing comprehension of this lesson: "${lessonTitle}".

Content summary: ${lessonContent}

Return ONLY valid JSON in this exact format, no other text:
{
  "questions": [
    {
      "q_ar": "question in Arabic",
      "q_en": "question in English",
      "options": ["option A", "option B", "option C", "option D"],
      "correct": 0,
      "explanation": "brief explanation of correct answer"
    }
  ]
}

Make questions appropriate for children learning Islamic studies. Include Arabic terminology.`
        }],
        system: 'You generate Islamic studies quiz questions for children. Always respond with valid JSON only.'
      })
    });

    const data = await response.json();
    const text = data.content?.[0]?.text || '{}';
    let quiz;
    try { quiz = JSON.parse(text.replace(/```json|```/g, '').trim()); }
    catch { throw new Error('Invalid JSON from API'); }

    renderAIQuiz(quiz, targetEl);
  } catch (err) {
    targetEl.innerHTML = `<p style="color:var(--tab-aqeedah)">Could not generate quiz. Check your connection.</p>`;
    console.error('AI quiz error:', err);
  }
}

function renderAIQuiz(quiz, targetEl) {
  if (!quiz?.questions?.length) {
    targetEl.innerHTML = '<p>No questions generated.</p>';
    return;
  }

  let html = '<div data-quiz="mcq" data-quiz-id="ai-generated">';
  quiz.questions.forEach((q, qi) => {
    html += `
      <div class="mcq-question" data-correct="${q.correct}">
        <p class="mcq-q-text">
          <span class="mcq-q-ar">${q.q_ar || ''}</span>
          ${q.q_en}
        </p>
        <div class="mcq-options">
          ${q.options.map((opt, oi) => `
            <button class="mcq-option" data-idx="${oi}">${opt}</button>
          `).join('')}
        </div>
        <p class="explanation" style="display:none;font-size:.85rem;color:var(--ink-light);margin-top:.5rem;padding:.5rem;background:var(--ivory);border-radius:var(--radius-sm)">
          💡 ${q.explanation || ''}
        </p>
      </div>
    `;
  });
  html += '</div>';
  targetEl.innerHTML = html;
  initMCQ(); // re-run MCQ init on new questions
}

window.generateAIQuiz = generateAIQuiz;

// ── Theme Switcher (per-student colour, saved to localStorage) ───
function initThemeSwitcher() {
  if (document.getElementById('theme-dock')) return;
  const current = document.documentElement.dataset.theme || 'lilac';
  const themes = [['lilac', '#8A5CCB'], ['emerald', '#0E8F66'], ['ocean', '#1E73C8'], ['red', '#C0392B'], ['sand', '#B89058'], ['royal', 'linear-gradient(135deg,#2C5FA8,#C99A2E)']];
  const dock = document.createElement('div');
  dock.id = 'theme-dock';
  dock.innerHTML =
    '<button class="theme-handle" aria-label="Change colour theme">THEME</button>' +
    '<div class="theme-panel" role="group" aria-label="Colour themes">' +
    themes.map(([t, c]) =>
      `<button class="theme-sw${t === current ? ' on' : ''}" data-theme-name="${t}" title="${t}" aria-label="${t} theme" style="background:${c}"></button>`
    ).join('') +
    '</div>';
  document.body.appendChild(dock);
  dock.querySelector('.theme-handle').addEventListener('click', () => dock.classList.toggle('collapsed'));
  dock.querySelectorAll('.theme-sw').forEach(sw => {
    sw.addEventListener('click', () => {
      const t = sw.dataset.themeName;
      document.documentElement.dataset.theme = t;
      localStorage.setItem('mdrs_theme', t);
      dock.querySelectorAll('.theme-sw').forEach(s => s.classList.toggle('on', s === sw));
    });
  });
}

// ── Floating Search (client-side, over MDRS_SEARCH) ──────────
function initSearch() {
  if (document.getElementById('search-fab')) return;
  const base = location.pathname.includes('/pages/') ? '../../' : '';
  const colors = { 'Islam 101':'--tab-islam101','Quran':'--tab-quran','Hadeeth':'--tab-hadeeth','Seerah':'--tab-seerah','Fiqh':'--tab-fiqh','Aqeedah':'--tab-aqeedah','Grammar':'--tab-grammar','Resources':'--tab-resources','Home':'--brand' };

  const fab = document.createElement('button');
  fab.id = 'search-fab';
  fab.setAttribute('aria-label', 'Search Dār al-Hijrah');
  fab.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><circle cx="10.5" cy="10.5" r="7"/><line x1="15.8" y1="15.8" x2="21" y2="21"/></svg><span>SEARCH</span>';
  const yearSel = document.querySelector('.header-inner .year-selector');
  const headerInner = document.querySelector('.header-inner');
  if (yearSel && headerInner) headerInner.insertBefore(fab, yearSel);
  else if (headerInner) headerInner.appendChild(fab);
  else document.body.appendChild(fab);

  const ov = document.createElement('div');
  ov.id = 'search-overlay';
  ov.hidden = true;
  ov.innerHTML =
    '<div class="search-box" role="dialog" aria-label="Search the school">' +
      '<div class="search-bar">' +
        '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="10.5" cy="10.5" r="7"/><line x1="15.8" y1="15.8" x2="21" y2="21"/></svg>' +
        '<input id="search-input" type="search" autocomplete="off" placeholder="Search lessons, sūrahs, ḥadīth, terms…">' +
        '<kbd>Esc</kbd>' +
      '</div>' +
      '<div id="search-results"></div>' +
    '</div>';
  document.body.appendChild(ov);

  const input = ov.querySelector('#search-input');
  const results = ov.querySelector('#search-results');

  function render(q) {
    q = (q || '').trim().toLowerCase();
    let items = MDRS_SEARCH;
    if (q) {
      items = MDRS_SEARCH.map(function (e) {
        const title = (e.t || '').toLowerCase();
        const hay = (title + ' ' + (e.s || '') + ' ' + (e.d || '')).toLowerCase();
        let score = -1;
        if (title.indexOf(q) === 0) score = 0;
        else if (title.indexOf(q) > -1) score = 1;
        else if (hay.indexOf(q) > -1) score = 2;
        return { e: e, score: score };
      }).filter(function (x) { return x.score >= 0; })
        .sort(function (a, b) { return a.score - b.score; })
        .map(function (x) { return x.e; });
    }
    items = items.slice(0, 12);
    if (!items.length) {
      results.innerHTML = '<p class="search-empty">No matches — try "tawhid", "fātiḥah", "iʿrāb", "wuḍūʾ" or "intention".</p>';
      return;
    }
    results.innerHTML = items.map(function (e) {
      const c = colors[e.s] || '--brand';
      return '<a class="search-result" href="' + base + e.u + '">' +
        '<span class="sr-dot" style="background:var(' + c + ')"></span>' +
        '<span class="sr-text"><span class="sr-title">' + e.t + '</span><span class="sr-sub">' + e.s + '</span></span></a>';
    }).join('');
  }

  function open() { ov.hidden = false; document.body.style.overflow = 'hidden'; render(''); setTimeout(function () { input.focus(); }, 30); }
  function close() { ov.hidden = true; document.body.style.overflow = ''; input.value = ''; }

  fab.addEventListener('click', open);
  input.addEventListener('input', function () { render(input.value); });
  ov.addEventListener('click', function (e) { if (e.target === ov) close(); });
  document.addEventListener('keydown', function (e) {
    const typing = /^(input|textarea|select)$/i.test(e.target.tagName);
    if ((e.key === 'k' || e.key === 'K') && (e.ctrlKey || e.metaKey)) { e.preventDefault(); ov.hidden ? open() : close(); }
    else if (e.key === '/' && !typing && ov.hidden) { e.preventDefault(); open(); }
    else if (e.key === 'Escape' && !ov.hidden) { close(); }
  });
}

